let require condition message = if not condition then failwith message
let get key value = Json.field key (Json.object_fields value)
let set key value raw = Json.Object ((key,value) :: List.remove_assoc key (Json.object_fields raw))
let str value = Json.String value
let arr value = Json.Array value
let rejected code action = match action () with
  | _ -> failwith ("Unexpected realization acceptance success: " ^ code)
  | exception Diagnostic.Error error -> require (error.code = code)
      ("Expected " ^ code ^ ", got " ^ error.code ^ ": " ^ error.message)
type fixture = {behavior:Behavior.t; contract:C.Behavior_contract.t; domain:C.Operating_domain.t;
  target:Build_request.Target.t; mechanism:Mechanism.t; observations:Observation_map.t; history:D.Input_frame.t list}
let decode value = {behavior=Behavior.of_json (get "behavior" value);
  contract=C.Behavior_contract.of_json (get "contract" value); domain=C.Operating_domain.of_json (get "domain" value);
  target=Build_request.Target.of_json (get "target" value); mechanism=Mechanism.of_json (get "mechanism" value);
  observations=Observation_map.of_json (get "observation_map" value);
  history=Json.array (get "history" value) |> List.map D.Input_frame.of_json}
let run ?until ?limits ?parent f = K.check ?until ?limits ?parent f.behavior f.contract f.domain f.target f.mechanism f.observations f.history
let measured ?until ?limits ?parent f = K.check_with_usage ?until ?limits ?parent f.behavior f.contract f.domain f.target f.mechanism f.observations f.history
let dependencies ?until ?limits ?parent f = K.dependencies ?until ?limits ?parent f.behavior f.contract f.domain f.target f.mechanism f.observations f.history
