let verify name ?until fixture =
  let result = run ?until fixture and wanted = get name expected in
  require (E.Check_result.fingerprint result = Json.string (get "fingerprint" wanted)) (name ^ ": complete independent result differs");
  require (E.Dependency_snapshot.fingerprint (dependencies ?until fixture) = Json.string (get "dependencies" wanted)) (name ^ ": complete dependency inventory differs");
  require (Canonical.encode (get "diagnostics" (E.Check_result.to_json result)) = Canonical.encode (get "diagnostics" wanted)) (name ^ ": source diagnostics differ"); result
let mechanism fixture change =
  let raw = Mechanism.to_json fixture.mechanism in
  {fixture with mechanism=Mechanism.of_json (set "nodes" (arr (List.map change (Json.array (get "nodes" raw)))) raw)}
let id raw = Json.string (get "id" raw)
let () =
  let base = decode base_json and contact = decode contact_json and division = decode division_json in
  let baseline = verify "baseline" base in
  ignore (verify "contact" contact);
  ignore (verify "silent" (mechanism base (fun node -> if id node = "delay" then set "inputs" (arr [str "low"]) node else node)));
  ignore (verify "always" (mechanism base (fun node -> if id node = "delay" then set "inputs" (arr [str "high"]) node else node)));
  ignore (verify "short" ~until:(N.Real 2.5) base);
  ignore (verify "negative_zero" ~until:(N.Real (-0.)) base);
  let explicit = verify "explicit" ~until:(N.of_int 10) base in
