  let wrong_contract = C.Behavior_contract.of_json (set "behavior_fingerprint" (str (String.make 64 'f')) (C.Behavior_contract.to_json base.contract)) in
  ignore (verify "identity" {base with contract=wrong_contract});
  ignore (verify "lineage" (mechanism base (fun node -> if id node = "output" then set "requirement_ids" (arr [str "unknown"]) node else node)));
  ignore (verify "missing" {base with history=D.Input_frame.make ~time:N.zero () :: List.tl base.history});
  let future = {base with history=base.history @ [D.Input_frame.make ~time:(N.of_int 20) ()]} in
  ignore (verify "future" ~until:(N.of_int 10) future);
  require (E.Dependency_snapshot.changed (dependencies ~until:(N.of_int 10) base) (dependencies ~until:(N.of_int 10) future) = ["history"])
    "Future unused observations disappeared from authority";
