  let relocated = Behavior.of_json (raw
    |> set "nodes" (arr (List.map relocated_record (Json.array (get "nodes" raw))))
    |> set "requirements" (arr (List.map relocated_record (Json.array (get "requirements" raw))))) in
  require (Behavior.fingerprint relocated = Behavior.fingerprint base.behavior) "Source-only edit changed semantic Behavior identity";
  require (E.Dependency_snapshot.changed (dependencies base) (dependencies {base with behavior=relocated}) = ["behavior_artifact"])
    "Full Unicode source artifact was omitted from evidence";
  let result, usage = measured base in
