  rejected "realization_input_limit" (fun () -> dependencies ~limits:(K.make_limits ~max_request_bytes:(dependency_usage.request_bytes - 1) ()) base);
  require (E.Check_result.fingerprint (run ~limits:(K.make_limits ~max_report_bytes:usage.report_bytes ()) base) = E.Check_result.fingerprint baseline)
