    | Json.Array values -> arr (List.map rename_input values)
    | Json.Object values -> Json.Object (List.map (fun (key,value) -> key,rename_input value) values)
    | value -> value in
  let amplified = {base with
    mechanism=Mechanism.of_json (rename_input (Mechanism.to_json base.mechanism));
    observations=Observation_map.of_json (rename_input (Observation_map.to_json base.observations));
    history=List.init 300 (fun index -> D.Input_frame.make ~time:(N.of_int index)
      ~signals:(D.Input_frame.signals first) ())} in
  let translated_parent = W.create ~profile:"literal.translation" ~error_code:"literal_translation_parent" ~maximum:50_000_000 () in
  rejected "realization_translation_limit" (fun () -> run ~parent:translated_parent amplified);
  require (W.remaining translated_parent < 35_000_000)
