  let repeated_parent = W.create ~profile:"literal.failure" ~error_code:"literal_failed_parent" ~maximum:50_000_000 () in
  let _, failed_usage = measured ~parent:repeated_parent division in
  require (W.remaining repeated_parent = 50_000_000 - failed_usage.work_charged)
    "Failed engine work reservation was reusable through a shared parent";
  require (E.Check_result.outcome (run base) = E.Pass) "A failed session leaked runtime state into a fresh check";
  print_endline "realization coordinator: exact full dependency/result literals, ordered preflight, independent fresh engines, full future authority, shared resource exhaustion and conservative failure accounting checked"
